  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Vismodegib, which shares the methylsulfonylphenyl and chlorinated heteroaryl core with the query, has a measured absolute bioavailability of 31.8% after a 150 mg oral dose in healthy subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Rofecoxib, a methylsulfonylphenyl-containing drug, has a mean oral bioavailability of approximately 93% in healthy volunteers, supporting high oral bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Valdecoxib, a methylsulfonylphenyl isoxazole, has an absolute bioavailability of 83% in humans, supporting high F for related methylsulfonylphenyl heteroaromatics.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Esaxerenone, another methylsulfonylphenyl-containing drug, has an absolute bioavailability of 89.0% in the fasting state in healthy subjects, directly matching the fasted condition and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "5-Hydroxyrofecoxib, the hydroxylated metabolite of rofecoxib, has low bioavailability (14.0% after a 25 mg oral dose), but the query lacks this additional polar hydroxyl group, so this contradictory evidence has limited structural transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is predicted high (F >= 20%) because multiple structurally related methylsulfonylphenyl/heteroaryl drugs show high absolute oral bioavailability (vismodegib 31.8%, rofecoxib ~93%, valdecoxib 83%, esaxerenone 89%). The only low example is a hydroxylated metabolite with limited transferability to the query.",
